//! Windows-only link settings for the desktop binary.
//!
//! Stack: Windows gives the main thread a 1 MiB stack, while Linux and macOS
//! give 8 MiB. GPUI builds whole element trees on the main thread, and
//! unoptimized builds keep every intermediate element in one frame, so match
//! the Unix size.
//!
//! Icon: GPUI loads the window icon from icon group resource 1 of the
//! executable, and Explorer, the taskbar and shortcuts show the same group.
//! `assets/wrongmemory-desktop.ico` (generated by
//! `scripts/desktop/build-icons.ts`) is converted to a compiled resource
//! (`.res`) here and passed to the MSVC linker, so no resource compiler or
//! extra build dependency is needed.
use std::path::Path;

const ICON: &str = "assets/wrongmemory-desktop.ico";
const RT_ICON: u16 = 3;
const RT_GROUP_ICON: u16 = 14;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={ICON}");
    let target_os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_env = std::env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
    if target_os == "windows" && target_env == "msvc" {
        println!("cargo:rustc-link-arg-bins=/STACK:8388608");
        let ico = std::fs::read(ICON).expect("read the desktop icon");
        let out =
            Path::new(&std::env::var("OUT_DIR").expect("OUT_DIR")).join("wrongmemory-desktop.res");
        std::fs::write(&out, icon_resources(&ico)).expect("write the icon resource");
        println!("cargo:rustc-link-arg-bins={}", out.display());
    }
}

/// One `.res` entry with a numeric type and name, neutral language.
fn resource(out: &mut Vec<u8>, kind: u16, id: u16, flags: u16, data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out.extend_from_slice(&32u32.to_le_bytes()); // header size
    out.extend_from_slice(&[0xFF, 0xFF]);
    out.extend_from_slice(&kind.to_le_bytes());
    out.extend_from_slice(&[0xFF, 0xFF]);
    out.extend_from_slice(&id.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // data version
    out.extend_from_slice(&flags.to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes()); // language
    out.extend_from_slice(&0u32.to_le_bytes()); // version
    out.extend_from_slice(&0u32.to_le_bytes()); // characteristics
    out.extend_from_slice(data);
    while !out.len().is_multiple_of(4) {
        out.push(0);
    }
}

fn u16_at(b: &[u8], at: usize) -> u16 {
    u16::from_le_bytes([b[at], b[at + 1]])
}

fn u32_at(b: &[u8], at: usize) -> u32 {
    u32::from_le_bytes([b[at], b[at + 1], b[at + 2], b[at + 3]])
}

/// Converts an `.ico` file into a `.res` holding each image as `RT_ICON`
/// 1..=n and the directory as `RT_GROUP_ICON` 1.
fn icon_resources(ico: &[u8]) -> Vec<u8> {
    assert!(
        ico.len() >= 6 && u16_at(ico, 0) == 0 && u16_at(ico, 2) == 1,
        "{ICON} is not an icon file"
    );
    let count = u16_at(ico, 4);
    // The leading empty entry marks a 32-bit resource file.
    let mut res = Vec::new();
    resource(&mut res, 0, 0, 0, &[]);
    let mut group = Vec::new();
    group.extend_from_slice(&0u16.to_le_bytes());
    group.extend_from_slice(&1u16.to_le_bytes());
    group.extend_from_slice(&count.to_le_bytes());
    for index in 0..count {
        let entry = 6 + 16 * index as usize;
        let size = u32_at(ico, entry + 8) as usize;
        let offset = u32_at(ico, entry + 12) as usize;
        let image = ico
            .get(offset..offset + size)
            .expect("icon image inside the file");
        let id = index + 1;
        resource(&mut res, RT_ICON, id, 0x1010, image);
        group.extend_from_slice(&ico[entry..entry + 12]);
        group.extend_from_slice(&id.to_le_bytes());
    }
    resource(&mut res, RT_GROUP_ICON, 1, 0x1030, &group);
    res
}
